script:
(function () {
  'use strict';
  // ---- Historical price data -------------------------------------------------------------
  // CPI-U, U.S. city average, all items, not seasonally adjusted, 1982-84 = 100: annual averages
  // as published by the U.S. Bureau of Labor Statistics (series CUUR0000SA0, period M13).
  // Source: https://data.bls.gov/timeseries/CUUR0000SA0 (retrieved 1 October 2026).
  // First year 1913, last year 2025. BLS publishes annual averages to one decimal before 2007
  // and to three decimals from 2007; values are kept exactly as published. The 2025 average
  // is the official BLS figure (October 2025 was not collected during the funding lapse).
  // Update once a year when BLS publishes the next annual average (mid-January).
  var CPI_FIRST_YEAR = 1913;
  var CPI = [
    9.9, 10.0, 10.1, 10.9, 12.8, 15.1, 17.3, 20.0, 17.9, 16.8,  // 1913-1922
    17.1, 17.1, 17.5, 17.7, 17.4, 17.1, 17.1, 16.7, 15.2, 13.7,  // 1923-1932
    13.0, 13.4, 13.7, 13.9, 14.4, 14.1, 13.9, 14.0, 14.7, 16.3,  // 1933-1942
    17.3, 17.6, 18.0, 19.5, 22.3, 24.1, 23.8, 24.1, 26.0, 26.5,  // 1943-1952
    26.7, 26.9, 26.8, 27.2, 28.1, 28.9, 29.1, 29.6, 29.9, 30.2,  // 1953-1962
    30.6, 31.0, 31.5, 32.4, 33.4, 34.8, 36.7, 38.8, 40.5, 41.8,  // 1963-1972
    44.4, 49.3, 53.8, 56.9, 60.6, 65.2, 72.6, 82.4, 90.9, 96.5,  // 1973-1982
    99.6, 103.9, 107.6, 109.6, 113.6, 118.3, 124.0, 130.7, 136.2, 140.3,  // 1983-1992
    144.5, 148.2, 152.4, 156.9, 160.5, 163.0, 166.6, 172.2, 177.1, 179.9,  // 1993-2002
    184.0, 188.9, 195.3, 201.6, 207.342, 215.303, 214.537, 218.056, 224.939, 229.594,  // 2003-2012
    232.957, 236.736, 237.017, 240.007, 245.120, 251.107, 255.657, 258.811, 270.970, 292.655,  // 2013-2022
    304.702, 313.689, 321.943  // 2023-2025
  ];
  var CPI_LAST_YEAR = CPI_FIRST_YEAR + CPI.length - 1;
  // ----------------------------------------------------------------------------------------
  // Historical: value in target year = amount x CPI(target) / CPI(start); cumulative inflation =
  // CPI(later) / CPI(earlier) - 1; average annual rate = (CPI(later) / CPI(earlier))^(1/years) - 1.
  // Future: cost after n years = amount x (1 + i)^n; today's value of a future amount = amount / (1 + i)^n.
  // Verified (scratchpad tests/inf.test.js): $100 in 1913 = $3,251.95 in 2025 (321.943 / 9.9);
  // $100 in 2000 = $182.17 in 2024 (313.689 / 172.2); 2022 inflation 8.0% (292.655 / 270.970);
  // 2009 deflation -0.4%; $100 at 3% for 10 years = $134.39 and $100 in 10 years = $74.41 today.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function cpi(year) { return CPI[year - CPI_FIRST_YEAR]; }
  function cpiText(year) { return cpi(year).toFixed(year < 2007 ? 1 : 3); }
  function pct(x, d) { return (x * 100).toFixed(d) + '%'; }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function historical(amount, from, to) {
    var lo = Math.min(from, to), hi = Math.max(from, to), rows = [];
    for (var y = lo; y <= hi; y++) {
      rows.push({ year: y, cpi: cpi(y), change: y > CPI_FIRST_YEAR ? cpi(y) / cpi(y - 1) - 1 : NaN,
                  value: amount * cpi(y) / cpi(from) });
    }
    var cumulative = cpi(hi) / cpi(lo) - 1;
    return { value: amount * cpi(to) / cpi(from), cumulative: cumulative,
             average: hi > lo ? Math.pow(cpi(hi) / cpi(lo), 1 / (hi - lo)) - 1 : 0, rows: rows };
  }

  function updateHistory() {
    var amount = num('infAmount'), from = parseInt(document.getElementById('infFrom').value, 10),
        to = parseInt(document.getElementById('infTo').value, 10);
    var error = document.getElementById('infError');
    var bad = isNaN(amount) || amount < 0 || isNaN(from) || isNaN(to) ||
              from < CPI_FIRST_YEAR || from > CPI_LAST_YEAR || to < CPI_FIRST_YEAR || to > CPI_LAST_YEAR;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter an amount of $0 or more and choose years from ' + CPI_FIRST_YEAR + ' to ' + CPI_LAST_YEAR + '.';
      ['infValue', 'infCumulative', 'infAverage', 'infCpi'].forEach(function (id) { set(id, '–'); });
      set('infSummary', '');
      document.getElementById('infTable').innerHTML = '';
      return;
    }
    var h = historical(amount, from, to);
    set('infValueLabel', 'Value in ' + to);
    set('infValue', money.format(h.value));
    set('infSummary', money.format(amount) + ' in ' + from + ' had the same buying power as ' + money.format(h.value) + ' in ' + to + '.');
    set('infCumulative', pct(h.cumulative, 1));
    set('infAverage', pct(h.average, 2));
    set('infCpi', cpiText(from) + ' → ' + cpiText(to));
    document.getElementById('infTable').innerHTML = h.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + cpiText(row.year) + '</td><td>' + (isNaN(row.change) ? '–' : pct(row.change, 1)) +
             '</td><td>' + money.format(row.value) + '</td></tr>';
    }).join('');
  }

  function updateFuture() {
    var amount = num('infFutAmount'), rate = num('infFutRate'), years = num('infFutYears');
    var error = document.getElementById('infFutError');
    var bad = [amount, rate, years].some(isNaN) || amount < 0 || rate < -50 || rate > 100 || years < 0 || years > 100;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter an amount of $0 or more, a rate from -50 to 100% and 0 to 100 years.';
      set('infFutCost', '–');
      set('infFutWorth', '–');
      return;
    }
    var factor = Math.pow(1 + rate / 100, years);
    set('infFutCost', money.format(amount * factor));
    set('infFutWorth', money.format(amount / factor));
  }

  document.addEventListener('DOMContentLoaded', function () {
    set('infDataNote', 'Uses BLS CPI-U annual averages from ' + CPI_FIRST_YEAR + ' to ' + CPI_LAST_YEAR + '.');
    [['infForm', updateHistory], ['infFutForm', updateFuture]].forEach(function (pair) {
      var form = document.getElementById(pair[0]);
      form.addEventListener('input', pair[1]);
      form.addEventListener('change', pair[1]);
      form.addEventListener('submit', function (e) { e.preventDefault(); });
      pair[1]();
    });
  });
})();
